import {hearButton} from './play-media.mjs';
import {pavingCases} from './garden-paving-content.mjs';
import {pavingView,pavingText,pavingCounts,maskPatches,parsePaving,startPaving,editPaving,supportPaving,checkPaving,keepPaving,recoverPaving,preflightPavingDisplay} from './garden-paving-core.mjs';
import {pavingPicture,pavingLegend} from './garden-paving-art.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,attrs,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const pages=['learn','build','kept'],names={learn:'Learn',build:'Build',kept:'Kept'};
const empty='<p id="paving-status" role="status" tabindex="-1"></p>';
export const pavingRef=w=>`<aside class="paving-reference"><p>${esc(pavingText(w.source.copy.reference,w))}</p></aside>`;
const answer=(w,key)=>w[key+'Mode']==='unsure'?'Not sure':w[key+'Input'].trim()===''?'Blank':w[key+'Input'];
const description=w=>pavingText(w.source.copy.narration,w);
const referenceText=w=>pavingText(w.source.copy.reference,w);
const proposals=w=>`New tiles proposed: ${answer(w,'added')}. Finished total proposed: ${answer(w,'total')}.`;
const recordReference=c=>{const n=c.snapshot.source.n;return `Old: ${n} × ${n} = ${n*n} tiles. Finished goal: ${n+1} × ${n+1} = ${(n+1)**2} tiles.`;};
const recordText=c=>recordReference(c)+' '+c.feedback;
function narration(v){if(!v.work)return 'Choose a square plan. Every plan is open.';const w=v.work;if(w.page==='kept')return v.kept?referenceText(v.kept.snapshot)+' '+description(v.kept.snapshot)+' '+proposals(v.kept.snapshot)+' '+(v.kept.check?recordText(v.kept.check):'Kept without a check.'):v.keptUnreadable?'An earlier kept version stays unreadable in the notes.':'Nothing kept yet.';return w.page==='learn'?pavingText(w.source.copy.idea,w)+' '+referenceText(w):pavingText(w.source.copy.reminder,w)+' '+referenceText(w)+' '+description(w)+' '+proposals(w);}
function figure(w,prefix='paving-live'){return `<figure class="paving-figure">${pavingPicture(w.source.n,w.patches,prefix)}<figcaption>${esc(pavingText(w.source.copy.currentCounts,w))}</figcaption></figure>`;}
function example(w,step){const e=w.source.example;return `<div data-paving-example-figure data-step="${step}">${pavingPicture(e.n,maskPatches(e.masks[step]),'paving-example')}<p>${esc(e.captions[step])}</p></div>`;}
function chooser(v){const sources=[pavingCases[2],...pavingCases.filter(s=>s.n!==3)];return `<details class="paving-chooser" ${v.work?'':'open'}><summary>Choose any square plan</summary><div class="paving-plan-list">${sources.map(s=>{const c=v.readable.find(c=>c.id===s.id),bad=v.unreadable.some(c=>c.id===s.id);return `<article><h3>${esc(c?.work.source.title||s.title)}</h3><p>Start ${c?.work.source.n||s.n} by ${c?.work.source.n||s.n}; grow each side by one.</p>${bad?'<p>Earlier unreadable work stays in your download. Other plans remain open.</p>':btn(c?'Resume this plan':'Start this plan',`data-paving-start="${s.id}"`)}</article>`;}).join('')}${v.readable.filter(c=>!pavingCases.some(s=>s.id===c.id)).map(c=>`<article><h3>${esc(c.work.source.title)}</h3>${btn('Resume earlier plan',`data-paving-start="${esc(c.id)}"`)}</article>`).join('')}</div></details>`;}
function record(c,current=false){return `<article class="paving-check" data-paving-record="${c.id}" ${current?`id="paving-check-${c.id}" data-paving-current`:''} tabindex="-1"><h3>${current?'Check of this version':'Earlier recorded check'} ${c.id}</h3>${pavingRef(c.snapshot)}<p class="paving-record-reference">${esc(recordReference(c))}</p><p>${esc(c.feedback)}</p>${btn('Hear this recorded check',`data-paving-record-hear="${esc(recordText(c))}"`)}<details><summary>Inputs and support</summary><p>${esc(proposals(c.snapshot))} Support: ${esc(c.snapshot.support.join(', ')||'none requested')}.</p><p>Pictured practice; prior exposure unknown.</p></details></article>`;}
function keptBody(v,prefix='kept'){return v.kept?`<h2>Our kept version</h2>${pavingRef(v.kept.snapshot)}${figure(v.kept.snapshot,`paving-${prefix}`)}<p>${esc(proposals(v.kept.snapshot))}</p>${v.kept.check?record(v.kept.check):'<p>This version was kept without a check.</p>'}`:v.keptUnreadable?'<p>The earlier kept copy cannot be read here. It stays unchanged in your download. Use a separate paving notebook to keep another version.</p>':'<p>Nothing kept yet. Unfinished work is welcome.</p>';}
function historyBody(v){return v.readableChecks.slice(-4).map(c=>record(c)).join('')+(v.rawChecks.length?'<p>Unreadable or duplicate checks stay unchanged in your download.</p>':'')+(!v.readableChecks.length?'<p>No readable checks yet.</p>':'');}
function inputs(w,key){const word=key==='added'?'new tiles':'finished total';return `<div class="paving-proposal"><label for="paving-${key}">${esc(pavingText(w.source.copy[key==='added'?'addedPrompt':'totalPrompt'],w))}</label><input id="paving-${key}" type="text" inputmode="numeric" autocomplete="off" value="${esc(w[key+'Input'])}" aria-describedby="paving-${key}-state"><p id="paving-${key}-state" class="tiny">${w[key+'Mode']==='unsure'?'Not sure selected.':'Propose a count, or leave it open.'}</p><div class="paving-modes">${btn('Not sure',`data-paving-unsure="${key}" aria-label="Not sure about ${word}"`)}${btn('Blank',`data-paving-blank="${key}" aria-label="Leave ${word} blank"`)}</div></div>`;}
export const pavingEntry=()=>'<section class="resume-strip"><div><h2>Garden Paving</h2><p>Keep the old square. Find what is added and what the finished square holds.</p><a class="secondary" href="#numbers/paving">Plan a bigger square</a></div></section>';
export const pavingRefusal='This change could not fit safely. Earlier work stays unchanged. Download notes, or use a separate explorer if the notebook is full.';
export function pavingRefusalPage(){return `<section class="paving-sheet" data-paving-blocked><h1 tabindex="-1">Garden Paving</h1><p id="paving-status" role="status" tabindex="-1">${pavingRefusal}</p><a class="secondary" href="#numbers">Back to Number Garden</a><a class="secondary" href="#notes">Download notes</a></section>`;}
export function pavingPage(state){
 const v=pavingView(state),head='<section class="paving-sheet" data-paving-root><a class="back" href="#numbers">Back to Number Garden</a>';
 if(v.status==='recovery')return head+'<h1 id="paving-title" tabindex="-1">Earlier paving work is kept</h1><p>The entire earlier notebook stays in your download. Start a separate notebook to make another plan.</p>'+btn('Start a separate paving notebook','data-paving-recover')+empty+'<a class="secondary" href="#notes">Download notes</a></section>';
 if(!v.work)return head+'<h1 id="paving-title" tabindex="-1">Garden Paving</h1><p>Moss is making room for a gathering table. Plan a bigger pretend tiled square.</p>'+chooser(v)+empty+'<a class="secondary" href="#notes">Download notes</a>'+(v.unreadable.length?btn('Start a separate paving notebook','data-paving-recover'):'')+'</section>';
 const w=v.work,s=w.source;let body='';
 if(w.page==='learn')body=`<p>${esc(pavingText(s.copy.idea,w))}</p><p>${esc(pavingText(s.copy.patches,w))}</p><div class="paving-example" data-paving-example>${example(w,0)}<div class="paving-actions">${[0,1,2].map(i=>btn('Example step '+(i+1),`data-paving-example-step="${i}" aria-pressed="${i===0}"`)).join('')}</div>${hearButton(s.example.captions[0],'Hear this example step').replace('<button ','<button data-paving-example-hear ')}</div>${btn('Go to our plan','data-paving-page="build"',true)}`;
 if(w.page==='build')body=`<p>${esc(pavingText(s.copy.reminder,w))}</p>${figure(w)}${pavingLegend()}<div class="paving-patches">${[['row','bottom patch',s.n],['column','right patch',s.n],['corner','corner',1]].map(([key,label,n])=>btn(`${w.patches[key]?'Remove':'Add'} ${label} (${n} ${n===1?'tile':'tiles'})`,`data-paving-patch="${key}" aria-pressed="${w.patches[key]}"`)).join('')}</div><div class="paving-proposals">${inputs(w,'added')}${inputs(w,'total')}</div>${v.readableChecks.length>=4?`<p class="tiny">The next check removes ${v.readableChecks.length-3} oldest readable check(s), leaving four recent checks. The kept copy stays. Download first for a longer record.</p>`:''}${btn('Check this plan','data-paving-check',true)}${v.feedback?record(v.feedback,true):'<p class="tiny">No check of this exact version is showing.</p>'}`;
 if(w.page==='kept')body=keptBody(v);
 return head+`<p class="paving-eyebrow">Garden Paving · ${pages.indexOf(w.page)+1} of 3</p><h1 id="paving-title" tabindex="-1">${({learn:'Old, new and altogether',build:'Build our bigger square',kept:'Our kept plan'})[w.page]}</h1>${pavingRef(w)}${hearButton('Request this turn’s current reading.','Hear this turn').replace('<button ','<button data-paving-hear ')}${empty}${body}<nav class="paving-actions" aria-label="Paving turns">${pages.map(p=>btn(names[p],`data-paving-page="${p}" aria-current="${w.page===p?'page':'false'}"`)).join('')}</nav>${btn(w.kept===null?'Keep this version':'Replace our kept version',`data-paving-keep ${v.keptUnreadable?'disabled':''}`)}${v.keptUnreadable?'<p>The earlier kept copy cannot be opened or replaced here. It stays in your download. Kept explains it; Help offers a separate notebook.</p>':''}<details class="paving-extras"><summary>Help, earlier plans and other squares</summary><p>${esc(s.request)}</p><details class="paving-help"><summary>Help with the pieces</summary><div data-paving-help-body></div>${hearButton('Open Help to read this explanation.','Hear this explanation')}</details>${btn('We thought together','data-paving-together')}<section data-paving-history>${btn('Show earlier checks','data-paving-history-open')}</section>${chooser(v)}<details><summary>Grown-ups: practice and recovery</summary><p>These countable diagrams and labels supply practice. They do not establish recall, physical area measurement or a full pattern/algebra curriculum.</p><a class="secondary" href="#notes">Download notes</a>${btn('Start a separate paving notebook','data-paving-recover')}</details></details></section>`;
}
export function pavingNotes(state){const v=pavingView(state);if(v.status==='missing')return '';return `<section class="paving-notes" data-paving-notes><h2>Garden Paving</h2><p>Pictured planning practice. Full source, checks, kept versions and unreadable work remain in this notebook file.</p>${hearButton('Saved paving plans are pictured practice. Show them if you would like to read together.','Hear about these notes')}${v.status==='recovery'?'<p>Earlier raw notebook retained; it cannot be opened here.</p>':btn('Show saved paving plans','data-paving-notes-open')}<p data-paving-notes-status role="status" tabindex="-1"></p><div data-paving-notes-body></div></section>`;}
function notesBody(state){const v=pavingView(state);return v.readable.map((c,i)=>`<section><h3>${esc(c.work.source.title)}</h3>${pavingRef(c.work)}${figure(c.work,`paving-notes-${i}`)}<p>${esc(proposals(c.work))}</p>${historyBody(c)}${keptBody(c,`notes-kept-${i}`)}</section>`).join('')+(v.unreadable.length?'<p>Unreadable earlier plans stay raw in your download. Other plans remain open.</p>':'');}
export function bindPaving(state,{save,render,focus,canExport,exposeFacts}={}){
 const scope=document.querySelector('[data-paving-root]'),notes=document.querySelector('[data-paving-notes]');
 if(!scope&&!notes){const blocked=document.querySelector('[data-paving-blocked] #paving-status');if(blocked)queueMicrotask(()=>{if(blocked.isConnected)focus?.('#paving-status');});return;}
 let boundRoot=state.gardenPaving;const boundCase=pavingView(state).root?.current??null;
 const live=(element,container=scope)=>!!container?.isConnected&&element?.isConnected&&container.contains(element)&&state.gardenPaving===boundRoot&&(pavingView(state).root?.current??null)===boundCase;
 const message=(text,refusal=false)=>{const n=document.querySelector(scope?'#paving-status':'[data-paving-notes-status]');if(n){n.textContent=text;if(refusal)focus?.(scope?'#paving-status':'[data-paving-notes-status]');}};
 const display=()=>({kind:pavingView(state).work?.page==='learn'?'example':'current',step:Number(scope?.querySelector('[data-paving-example-figure]')?.dataset.step||0)});
 const options=d=>({canExport,exposeFacts,display:d||display()});
 const run=(fn,target)=>{if(!live(scope))return false;if(!fn()){message(pavingRefusal,true);return false;}boundRoot=state.gardenPaving;save?.();render?.();if(target)focus?.(target);return true;};
 const supplied=(kind,e,d)=>{if(!live(scope))return false;if(!supportPaving(state,kind,options(d))){message(pavingRefusal,true);e?.stopImmediatePropagation();return false;}boundRoot=state.gardenPaving;save?.();if(!pavingView(state).feedback)scope.querySelectorAll('[data-paving-current]').forEach(c=>{c.removeAttribute('data-paving-current');c.querySelector('h3').textContent='Earlier recorded check '+c.dataset.pavingRecord;});return true;};
 const bind=(selector,fn)=>scope?.querySelectorAll(selector).forEach(b=>b.addEventListener('click',e=>{if(live(b))fn(b,e);}));
 const confirm=(recovery,fn)=>{const d=document.createElement('dialog'),captured=state.gardenPaving;d.innerHTML=`<div class="dialog-content"><h2>${recovery?'Start a separate paving notebook?':'Replace our kept version?'}</h2><p>${recovery?'The entire earlier paving notebook, including readable, kept and raw work, stays in your download.':'This overwrites the one earlier kept version for this plan.'} Download notes first for another copy.</p><button class="secondary" data-paving-cancel>Keep this page</button><button class="primary" data-paving-confirm>Yes, continue</button></div>`;document.body.append(d);d.showModal();d.querySelector('[data-paving-cancel]').onclick=()=>d.close();d.querySelector('[data-paving-confirm]').onclick=()=>{if(!d.isConnected||!d.open||!live(scope)||captured!==state.gardenPaving)return;d.close();run(fn,'#paving-title');};d.addEventListener('close',()=>d.remove());};
 bind('[data-paving-start]',b=>run(()=>startPaving(state,b.dataset.pavingStart,{canExport,exposeFacts}),'#paving-title'));
 bind('[data-paving-page]',b=>run(()=>editPaving(state,'page',b.dataset.pavingPage,{canExport,exposeFacts}),'#paving-title'));
 bind('[data-paving-patch]',b=>run(()=>editPaving(state,'patch',b.dataset.pavingPatch,options()),`[data-paving-patch="${b.dataset.pavingPatch}"]`));
 for(const key of ['added','total']){const input=scope?.querySelector('#paving-'+key);let prior=null;input?.addEventListener('beforeinput',()=>{if(live(input))prior=[input.selectionStart,input.selectionEnd];});input?.addEventListener('input',()=>{if(!live(input))return;const before=pavingView(state).work,selection=prior||[input.selectionStart,input.selectionEnd];prior=null;if(!editPaving(state,key+'Input',input.value,options())){input.value=before[key+'Input'];input.setSelectionRange(...selection.map(x=>Math.min(x??input.value.length,input.value.length)));message(pavingRefusal,true);return;}boundRoot=state.gardenPaving;save?.();scope.querySelector('#paving-'+key+'-state').textContent='Propose a count, or leave it open.';scope.querySelectorAll('[data-paving-current]').forEach(c=>{c.removeAttribute('data-paving-current');c.querySelector('h3').textContent='Earlier recorded check '+c.dataset.pavingRecord;});});}
 bind('[data-paving-unsure]',b=>run(()=>editPaving(state,b.dataset.pavingUnsure+'Mode','unsure',options()),`[data-paving-unsure="${b.dataset.pavingUnsure}"]`));
 bind('[data-paving-blank]',b=>run(()=>editPaving(state,b.dataset.pavingBlank+'Input','',options()),'#paving-'+b.dataset.pavingBlank));
 bind('[data-paving-check]',()=>{const w=pavingView(state).work;for(const key of ['added','total'])if(w[key+'Mode']==='input'&&parsePaving(w[key+'Input']).kind==='invalid'){message('Use a whole number from 0 to 144, leave it blank, or choose Not sure. Your draft stays open.');focus?.('#paving-'+key);return;}if(run(()=>checkPaving(state,options())))focus?.('#paving-check-'+pavingView(state).feedback.id);});
 bind('[data-paving-keep]',()=>{const v=pavingView(state);if(v.keptUnreadable)return;if(v.work.kept!==null)confirm(false,()=>keepPaving(state,true,options()));else if(run(()=>keepPaving(state,false,options()))){message('This version is kept.');focus?.('#paving-status');}});
 bind('[data-paving-recover]',()=>confirm(true,()=>recoverPaving(state,{canExport,exposeFacts})));
 bind('[data-paving-together]',(_b,e)=>{if(supplied('together',e))message('Thinking together is recorded.');});
 scope?.querySelector('.paving-help > summary')?.addEventListener('click',e=>{if(!live(e.currentTarget))return;if(!e.currentTarget.parentElement.open){if(!supplied('help',e,{...display(),reveal:'help'})){e.preventDefault();return;}const text=pavingText(pavingView(state).work.source.copy.help,pavingView(state).work);scope.querySelector('[data-paving-help-body]').textContent=text;scope.querySelector('.paving-help [data-speak]').dataset.speak=text;}});
 bind('[data-paving-example-step]',(b,e)=>{const step=Number(b.dataset.pavingExampleStep);if(!supplied('example',e,{kind:'example',step}))return;scope.querySelector('[data-paving-example-figure]').outerHTML=example(pavingView(state).work,step);scope.querySelector('[data-paving-example-hear]').dataset.speak=pavingView(state).work.source.example.captions[step];scope.querySelectorAll('[data-paving-example-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));message('Example step '+(step+1)+'. Your own plan stays unchanged.');});
 bind('[data-paving-history-open]',()=>{if(!preflightPavingDisplay(state,options({kind:'history'}))){message(pavingRefusal,true);return;}boundRoot=state.gardenPaving;save?.();scope.querySelector('[data-paving-history]').innerHTML=historyBody(pavingView(state));});
 scope?.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.stopImmediatePropagation();return;}const turn=b.hasAttribute('data-paving-hear'),example=b.hasAttribute('data-paving-example-hear'),help=!!b.closest('.paving-help');const text=turn?narration(pavingView(state)):help?pavingText(pavingView(state).work.source.copy.help,pavingView(state).work):b.dataset.speak;if(supplied(example?['example','narrationRequested']:help?['help','narrationRequested']:'narrationRequested',e,{...display(),reveal:turn?'narration':help?'help':null}))b.dataset.speak=text;}));
 // Revealed records use the existing explicit local speech event, avoiding rebinding other Hear buttons.
 const recordHear=(container,isNotes)=>container?.addEventListener('click',e=>{const b=e.target.closest('[data-paving-record-hear]');if(!b||!live(b,container))return;const opts=options({kind:isNotes?'notes':pavingView(state).work?.page==='kept'?'current':'history'});if(isNotes){if(!preflightPavingDisplay(state,opts)){message(pavingRefusal,true);return;}}else if(!supplied('narrationRequested',e,opts.display))return;boundRoot=state.gardenPaving;save?.();document.dispatchEvent(new CustomEvent('garden-speak-request',{detail:{text:b.dataset.pavingRecordHear,language:'en'}}));});
 recordHear(scope,false);recordHear(notes,true);
 notes?.querySelector('[data-paving-notes-open]')?.addEventListener('click',e=>{if(!live(e.currentTarget,notes))return;if(!preflightPavingDisplay(state,{canExport,exposeFacts,display:{kind:'notes'}})){message(pavingRefusal,true);return;}boundRoot=state.gardenPaving;save?.();notes.querySelector('[data-paving-notes-body]').innerHTML=notesBody(state);e.currentTarget.remove();});
}
